<div class="admin-filter-tabs"><?php foreach (['pendente'=>'Pendentes','aprovado'=>'Aprovados','rejeitado'=>'Rejeitados','suspenso'=>'Suspensos','todos'=>'Todos'] as $key=>$label): ?><a class="<?= $filter===$key?'is-active':'' ?>" href="<?= e(url('/admin/profissionais?estado='.$key)) ?>"><?= e($label) ?></a><?php endforeach; ?></div>
