    <?php foreach ($items as $person): ?><tr><td><strong><?= e($person['nome']) ?></strong><small><?= e($person['especialidade']) ?></small><small>Enviada em <?= e(date('d/m/Y', strtotime($person['submetido_em']))) ?></small></td><td><?= e($person['email']) ?><small><?= e($person['telefone']) ?></small></td><td><?= e($person['cedula_profissional']) ?><small><?= e($person['formacao'] ?: 'Formação não indicada') ?></small></td><td><?= e(trim(($person['municipio'] ?: '') . ' · ' . $person['provincia'], ' ·')) ?><small><?= e(ucfirst($person['modalidade'])) ?></small></td><td><span class="status-pill status-<?= e($person['estado']) ?>"><?= e(ucfirst($person['estado'])) ?></span></td><td><details class="review-details"><summary>Rever candidatura</summary><form method="post" action="<?= e(url('/admin/profissionais/'.$person['id'].'/decisao')) ?>"><?= csrf_field() ?><label>Nota de revisão<textarea name="nota_revisao" rows="3" maxlength="2000"><?= e($person['nota_revisao'] ?? '') ?></textarea></label><div class="review-actions"><button name="decisao" value="aprovado" class="review-approve" type="submit">Aprovar</button><button name="decisao" value="rejeitado" class="review-reject" type="submit">Rejeitar</button><button name="decisao" value="suspenso" class="review-suspend" type="submit">Suspender</button></div></form></details></td></tr><?php endforeach; ?>
    </tbody></table></div><?php else: ?><div class="admin-empty-state"><span>♧</span><h3>Não existem registos nesta categoria.</h3><p>As candidaturas e os perfis serão apresentados aqui.</p></div><?php endif; ?>
</section>
